package akogen.fabric.v6;
import java.nio.file.*;import java.util.*;
public final class RigChecks{
 static void require(boolean b,String s){if(!b)throw new AssertionError(s);}static double distance(double[]a,double[]b){double d=0;for(int i=0;i<3;i++)d+=(a[i]-b[i])*(a[i]-b[i]);return Math.sqrt(d);}
 static double[] bottom(Models.Bone b){double x=0,z=0,y=1e9;int n=0;for(float[]f:b.faces)for(int i=0;i<4;i++)y=Math.min(y,f[i*8+1]);for(float[]f:b.faces)for(int i=0;i<4;i++)if(Math.abs(f[i*8+1]-y)<.001){x+=f[i*8];z+=f[i*8+2];n++;}return new double[]{x/n,y,z/n};}
 public static void main(String[]args)throws Exception{Assets.load(Files.readAllBytes(Paths.get(args[0])));int balloons=0,hats=0,gaits=0;
 for(Assets.Entry e:Assets.entries){Models.Model m=Models.load(e);Expr.Context c=new Expr.Context();c.time=1.4;m.activeAnimations=Models.active(m,c,false);
 if(m.balloon){for(Models.Bone b:m.bones)if(b.name.equals("verity_balloon")||b.name.equals("tung_balloon")){Models.Bone k=m.byName.get(b.parent);double[] center=bottom(b);for(double t:new double[]{0,1.4,3.9,10.2}){c.time=t;Map<String,Models.Mat> done=new HashMap<String,Models.Mat>();Models.Mat p=Models.pose(m,b,c,false,done,0,0),q=Models.pose(m,k,c,false,done,0,0);double delta=distance(p.point(center[0],center[1],center[2]),q.point(k.pivot[0],k.pivot[1],k.pivot[2]));require(delta<.03,e.name+" balloon/rope gap: "+delta);}balloons++;}}
 if(m.hat){Map<String,Models.Mat> done=new HashMap<String,Models.Mat>();c.time=2;double y=1e9;for(Models.Bone b:m.bones){if(m.headHat&&!b.name.equals("torso"))continue;Models.Mat p=Models.pose(m,b,c,false,done,0,0);for(float[]f:b.faces)for(int i=0;i<4;i++)y=Math.min(y,p.point(f[i*8],f[i*8+1],f[i*8+2])[1]);}require(Math.abs(y-(m.headHat?29.0:29.65))<.02,e.name+" hat does not touch head: "+y);hats++;}
 if(e.slot.equals("shoes")){Models.Bone b=m.byName.get("verity_left_boot");if(b==null)b=m.byName.get(e.name.split(" ")[0].toLowerCase(Locale.ROOT)+"_slipper_left");require(b!=null&&!b.faces.isEmpty(),e.name+" missing shoe geometry");c.limbSpeed=0;Models.Mat p=Models.pose(m,b,c,false,new HashMap<String,Models.Mat>(),0,0);c.limbSpeed=.7;c.limbPos=2;Models.Mat q=Models.pose(m,b,c,false,new HashMap<String,Models.Mat>(),0,0);float[]f=b.faces.get(0);require(distance(p.point(f[0],f[1],f[2]),q.point(f[0],f[1],f[2]))>.2,e.name+" boots do not follow leg gait");gaits++;}
 if(e.slot.equals("wrist")){Models.Bone band=m.byName.get("tung_watch_band");require(band!=null&&!band.faces.isEmpty(),"Watch mesh missing");Models.Bone root=m.byName.get("tung_watch_root");require("bipedRightArm".equals(root.parent),"Watch is not attached to right arm");float[] f=band.faces.get(0);c.armRig=true;Models.Mat rest=Models.pose(m,band,c,false,new HashMap<String,Models.Mat>(),0,0);c.armRotX=55;Models.Mat moving=Models.pose(m,band,c,false,new HashMap<String,Models.Mat>(),0,0);require(distance(rest.point(f[0],f[1],f[2]),moving.point(f[0],f[1],f[2]))>2,"Watch does not follow actual right-arm pose");c.armRig=false;}
 if(e.name.equals("Tung Tung Tung Sahur")){c.speed=0;double a=Expr.eval("25*math.sin(query.anim_time*720)*math.min(1,query.ground_speed*10)",c);c.speed=-2.9;double b=Expr.eval("25*math.sin(query.anim_time*720)*math.min(1,query.ground_speed*10)",c);require(Math.abs(b-a)>1,"Tung gait speed variable missing");}
 if(m.duo){c.time=2;Map<String,Models.Mat> poses=new HashMap<String,Models.Mat>();Models.Bone l=m.byName.get(m.duoFirst+"left_arm"),r=m.byName.get(m.duoSecond+"right_arm");double[] a=Models.pose(m,l,c,false,poses,0,0).point(l.pivot[0],4.475,l.pivot[2]),b=Models.pose(m,r,c,false,poses,0,0).point(r.pivot[0],4.475,r.pivot[2]);require(distance(a,b)<1.2,"Duo inner hands do not meet: "+distance(a,b));}
 }
 require(balloons==2&&hats==7&&gaits==4,"Incomplete rig check coverage: "+balloons+" "+hats+" "+gaits);System.out.println("PASS 2 connected balloons at four sway times, 7 fitted hats, 4 vanilla leg gait bindings, Tung ground-speed animation, duo hand contact and real-arm watch binding");}
}
